#!/usr/bin/env python3
"""RESULTS.md of the float M5 part from results_first_run.json and results.json."""
import json, os, statistics as st
HERE = os.path.dirname(os.path.abspath(__file__))
first = {r["name"]: r for r in json.load(open(os.path.join(HERE, "results_first_run.json")))["rows"]}
rows = json.load(open(os.path.join(HERE, "results.json")))["rows"]
cnt = lambda rs, v: sum(r["verdict"] == v for r in rs)
ok = lambda r: r.get("gpu_mismatch") is None and "gpu_error" not in r
out = ["# M5, float part (NVIDIA A10G)", "",
       "Generated by `report_float.py`. The 22 tasks in `tasks.json` were written by the agent (Claude, an LLM)",
       "in one pass before any was checked: 16 meant to be correct and 6 with a seeded defect. 21 kernels share",
       "one skeleton (`write_kernels.py`: index, bound check, loads, the task's instruction lines, store); the",
       "grid-stride `f_saxpy_stride.ptx` is written by hand. Specs (`mkspec.py`) state each output element as an",
       "expression of the model's float operations, bit-exact up to NaN payloads.", "",
       "The GPU test runs each kernel and a CUDA C baseline (nvcc -O3, the intrinsic of the same rounding:",
       "`__fmaf_rn`, `__fdiv_rn`, ...; `-ftz=true` where the task flushes) on the same inputs (edge values,",
       "random bit patterns, random normal numbers), 133,094 elements per task (199,641 for the stride kernel),",
       "and requires equal bits, any NaN matching any NaN. The baseline does not use the Lean model.", "",
       "| | kernels | proved | refuted | unknown | unsupported |", "|---|---|---|---|---|---|"]
for lab, sel in (("written to be correct", False), ("seeded defect", True)):
    for run, src in (("first run", list(first.values())), ("after the fix", rows)):
        rs = [r for r in src if r.get("seeded", False) == sel]
        out.append(f"| {lab}, {run} | {len(rs)} | {cnt(rs,'proved')} | {cnt(rs,'refuted')} | {cnt(rs,'unknown')} | {cnt(rs,'unsupported')} |")
pr = [r for r in rows if r["verdict"] == "proved"]
lt = sorted(r["lean_seconds"] for r in pr if r.get("lean_seconds"))
sp = [r["baseline_us"] / r["ptx_us"] for r in pr if r.get("ptx_us") and r.get("baseline_us")]
out += ["", f"- Lean proof time per proved kernel: median {st.median(lt):.1f} s, max {lt[-1]:.1f} s (one Lean thread).",
        f"- All {len(pr)} proved kernels agree with the baseline on the GPU; every seeded defect except the",
        "  unsupported one differs from it.",
        f"- Speed, baseline time / PTX time at 2^24 elements: median {st.median(sp):.2f} ({min(sp):.2f} to {max(sp):.2f}).",
        "- The fix after the first run: `fbug_axpy_fused` (an fma where the spec rounds the product first) was",
        "  `unknown` because the counterexample search tried 44 small launches of random bit patterns and found",
        "  no input where the two roundings differ. The search now also draws normal numbers of nearby",
        "  magnitude and tries 2000 one-element launches for float maps; it then found one (replayed in Lean).",
        "- `fbug_div_approx` uses `div.approx.f32`, which the model refuses (no exact specification).",
        "", "| kernel | first run | now | counterexample | Lean s | GPU vs baseline | note |", "|---|---|---|---|---|---|---|"]
for r in rows:
    f = first.get(r["name"], {})
    note = (r["reasons"][0][:90] if r["verdict"] in ("unknown", "unsupported") and r.get("reasons") else "")
    if r.get("seeded"):
        note = ("seeded: " + r["task"].split(": ", 1)[-1] + ("; " + note if note else ""))
    out.append(f"| {r['name']} | {f.get('verdict','')} | {r['verdict']} | {r.get('counterexample') or ''} | "
               f"{r.get('lean_seconds') or ''} | {'agrees' if ok(r) else 'differs'} | {note.replace('|','/')} |")
open(os.path.join(HERE, "RESULTS.md"), "w").write("\n".join(out) + "\n")
print("\n".join(out[:20]))
